INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (8783, 'Tìm kiếm khách hàng mới', 'tim-kiem-khach-hang-moi', '		<div data-elementor-type="wp-post" data-elementor-id="8783" class="elementor elementor-8783" data-elementor-post-type="post">
				<div class="elementor-element elementor-element-2a4e0a8 e-con-full e-flex e-con e-parent" data-id="2a4e0a8" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
		<div class="elementor-element elementor-element-06aa645 e-con-full e-flex e-con e-parent" data-id="06aa645" data-element_type="container" data-settings="{&quot;background_background&quot;:&quot;classic&quot;,&quot;jet_parallax_layout_list&quot;:[]}">
